import{_ as i,l as o,o as e,c as n,v as r,p as s,x as l,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"杂散光与 flare","description":"","frontmatter":{"title":"杂散光与 flare","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/flare-and-stray.md","filePath":"litho/flare-and-stray.md","lastUpdated":1789023840000}'),f={name:"litho/flare-and-stray.md"};function m(E,a,A,c,D,_){const t=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="杂散光与-flare" tabindex="-1">杂散光与 flare <a class="header-anchor" href="#杂散光与-flare" aria-label="Permalink to &quot;杂散光与 flare&quot;">​</a></h1><div class="epigraph"><p>Flare 是不该参与成像的光：散射与杂散把一份缓变底座加进空中像，暗区变亮，全场对比随图形密度而变。</p><footer>—— 据 Mack、Levinson 对 flare 的定义；EUV 多层膜粗糙散射见 Bakshi 的公开论述</footer></div><p><a href="/litho/yieldstar-dbo">上一课</a>（YieldStar 与扫描仪内计量）。在此之上，位置计量钉在标记上。缺口是剂量底座：镜头、腔体与掩模的散射并不进「理想 TCC」，却给 \\(I(x,y)\\) 加上长程背景，使上一课程定义的对比度 \\(C\\) 在全场尺度上下降。本课钉 flare。计量课程到此结束；水作介质抬 \\(\\mathrm{NA}\\) 从<a href="/litho/arf-immersion">下一课</a>开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空中像课的 \\(C\\) 是局部、理想光学的。真实物镜有表面粗糙、镀膜缺陷、机械结构的反射，EUV 多层膜还有带内散射。一部分光离开设计的衍射级，以大范围晕斑落在晶圆上。暗区 \\(I_\\mathrm{min}\\) 被抬高，NILS 掉，E–D 窗口按图形密度缩——开阔区周围的密图形和密区里的孤立暗线，吃到的底座不同。</p><p>缺口因此是给这层底座一个名字和尺度，而不是再设计一套套刻垫。没有 flare，OPC 会把「开阔区 CD 偏大」修到掩模上，根子却在长程散射。</p><h3 id="kirk-测试量的是总底座" tabindex="-1">Kirk 测试量的是总底座 <a class="header-anchor" href="#kirk-测试量的是总底座" aria-label="Permalink to &quot;Kirk 测试量的是总底座&quot;">​</a></h3><p>经典 Kirk flare：在大暗区里开不同尺寸的亮垫（或反过来），看多大的暗区仍能被胶打印，从而估散射到该点的背景比例。它给出一个积分量，不自动给出点扩散的长尾形状。产线还要区分局部 flare（几十到几百微米）与全场/腔体杂散。</p><p><span class="marginnote">EUV 的 flare 往往比浸没 DUV 更疼：多层膜中频粗糙把可观能量打进散射，公开讨论里总 flare 可到几个百分点量级，且随空间频率分。具体机台数字用厂商公开值，不编造。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模把 flare 写成对空中像的长程卷积，或加一个与开孔率成正比的 DC 项再加中程核。OPC 必须吃进开孔率依赖：同一条线在 10% 与 70% 开孔率下有效剂量不同。补偿是局部剂量调整或掩模偏置，不能靠把 \\(\\gamma\\) 做陡来「切掉」DC——底座抬的是 \\(I_\\mathrm{min}\\)，陡胶仍然看见被抬高的暗区。</p><p>清洁、镀膜、光阑和腔体黑化减 DUV 杂散；EUV 还靠多层膜中频粗糙规格、光阑与真空腔设计。Pellicle 挡的是颗粒，不是镜面散射。</p><h3 id="与部分相干的区别" tabindex="-1">与部分相干的区别 <a class="header-anchor" href="#与部分相干的区别" aria-label="Permalink to &quot;与部分相干的区别&quot;">​</a></h3><p>\\(\\sigma\\) 描述的是故意引入的照明光瞳填充，TCC 已经包含。Flare 是设计光路之外的能量再分配，通常不进标称 TCC，要另加。不要把「\\(\\sigma\\) 太大对比差」和「flare 抬 \\(I_\\mathrm{min}\\)」写成同一个旋钮。</p>',14)),(e(),s(p,null,{default:l(()=>[d(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDEAL%5B%22%E7%90%86%E6%83%B3%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20ADD%5B%22%E5%8A%A0%E9%95%BF%E7%A8%8B%E6%95%A3%E5%B0%84%E5%BA%95%E5%BA%A7%22%5D%0A%20%20ROUGH%5B%22%E8%A1%A8%E9%9D%A2%20%2F%20%E5%A4%9A%E5%B1%82%E8%86%9C%E7%B2%97%E7%B3%99%22%5D%20--%3E%20ADD%0A%20%20ADD%20--%3E%20C%5B%22%E5%85%A8%E5%9C%BA%20C%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DENS%5B%22%E5%BC%80%E5%AD%94%E7%8E%87%22%5D%20--%3E%20ADD%0A%20%20C%20--%3E%20PW%5B%22E%E2%80%93D%20%E7%AA%97%E5%8F%A3%E9%9A%8F%E5%AF%86%E5%BA%A6%E5%8F%98%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>短程散射（几微米内）有时与镜头像差难分，表现像对比损失。长程 flare 让晶圆上一点看见整场开孔率的加权和：亮场给暗图形漏光，等效剂量增加、CD 按衬度曲线移动。扫描狭缝积分会把狭缝外的杂散也扫进来，时间上仍是底座。</p><p>套刻标记的对比也会被 flare 稀释，但位移偏置不是 flare 的一阶效应；一阶是 CD 与窗口。把 overlay 漂移全写到 flare 上，会修错。</p><h3 id="暗场掩模从源头减底座" tabindex="-1">暗场掩模从源头减底座 <a class="header-anchor" href="#暗场掩模从源头减底座" aria-label="Permalink to &quot;暗场掩模从源头减底座&quot;">​</a></h3><p>版图与掩模类型决定开孔率。暗场（尽量少透光）让长程积分变小，这是设计规则与 att-PSM / 二元选择的接口，不是镜头镀膜能单独买到的。剂量补偿按局部透光率加减，只能扳回平均 CD，扳不回已经损失的 \\(C\\)。元件 TIS（总积分散射）是镜子合同，整机 flare 还含腔体与掩模，不能用一张镜子的 TIS 代替 Kirk 测试。</p><p><span class="marginnote">浸没水层的气泡、水印是流体缺陷，不是本课的镜头 flare。计量课程到此结束：CD、套刻、剂量底座三张尺子都已点名。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某代 NXE 的 flare 百分比写成普适常数。也不讨论鬼像的每一个机械来源。浸没水中的气泡与颗粒散射是另一类缺陷，不要并进镜头 flare 规格。后课默认：说到对比度，量产还要问开孔率与 flare 模型是否在 OPC 里。</p><p>成像与胶的主干到计量为止已经闭合。下一课程从 ArF 浸没的介质 \\(n\\) 重新加一档 \\(\\mathrm{NA}\\)。镜头像差（球差、彗差）是设计波前，不是 flare；两者都会掉 NILS，修正手段不同——一个靠透镜与照明，一个靠散射控制与密度补偿。</p><p><span class="marginnote">全场开孔率随产品而变。存储器阵列几乎匀，逻辑后段疏密差大，flare 指纹更毒。同一台镜头、不同产品，有效 \\(C\\) 可以不是同一个数。</span></p><p>成像与胶的主干到计量为止已经闭合。下一课程从 ArF 浸没的介质 \\(n\\) 重新加一档 \\(\\mathrm{NA}\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Flare 是长程杂散底座，抬 \\(I_\\mathrm{min}\\)，对比随开孔率变。</li><li>Kirk 一类测试给积分量；OPC 需要有空间核的模型。</li><li>陡胶切不掉 DC；要减散射或按密度补偿剂量。</li><li>\\(\\sigma\\) 是故意的部分相干，flare 不是。</li><li>计量课程结束；下一课进入浸没 DUV。</li><li>出处：Mack / Levinson 对 flare 的讨论；Bakshi, <em>EUV Lithography</em> 对多层膜散射。</li></ul>',13))])}const B=i(f,[["render",m]]);export{u as __pageData,B as default};
